#!/usr/bin/env python3
import html, json, os
from string import Template
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__))); D=os.path.join(ROOT,'data'); OUT=os.path.join(ROOT,'docs','index.html')

def load(p):
    try:
        with open(os.path.join(D,p),encoding='utf-8') as f:return json.load(f)
    except Exception:return {}
def esc(v): return html.escape(str(v if v is not None else '-'))
def n(v,d=0):
    try:return float(v)
    except:return d
def pct(v):return f'{n(v):+.1f}%'
def pc(v):return 'up' if n(v)>=0 else 'down'
def tags(v,limit=6):
    if isinstance(v,dict): x=[f'{k}: {val}' for k,val in v.items() if val not in ('',None,False,0)]
    elif isinstance(v,(list,tuple,set)): x=[str(a) for a in v]
    elif v in ('',None): x=[]
    else:x=[str(v)]
    return ''.join(f'<span class="tag">{esc(a)}</span>' for a in x[:limit]) or '<span class="muted">暂无</span>'
def card(r,i):
    rec=r.get('recency') or {}; res=r.get('resonance') or {}; hist=r.get('history') or {}; rc=int(n(res.get('count')))
    return f'''<article class="stock"><div class="rank">TOP {i}</div><div class="name"><b>{esc(r.get('name'))}</b><small>{esc(r.get('code'))} · {esc(r.get('sector','-'))}</small></div><div><strong>{esc(r.get('price'))}</strong><span class="{pc(r.get('change_pct'))}">{pct(r.get('change_pct'))}</span></div><div class="score"><b>{n(r.get('adjusted_total')):.1f}</b><small>调整分</small></div><span class="pill">P{esc(rec.get('tier'))} {esc(rec.get('tag'))}</span><div class="metrics"><span>共振 <b class="gold">{'●'*rc+'○'*max(0,3-rc)}</b></span><span>连板概率 <b>{esc(r.get('lianban_probability'))}%</b></span><span>换手 <b>{esc(r.get('turnover_rate'))}%</b></span><span>历史涨停 <b>{esc(hist.get('limit_up_count'))}</b></span></div><details><summary>七因子 / 资金 / K线</summary><div class="tags">{tags(r.get('next_day_watch'),8)}{tags(r.get('capital_signals'),6)}{tags(r.get('kline_signals'),6)}</div></details></article>'''
def rows(rs):
    return ''.join(f'<div class="row"><b>{esc(r.get("name"))}</b><span>{esc(r.get("code"))}</span><span class="pill">P{esc((r.get("recency") or {}).get("tier"))}</span><strong>{n(r.get("adjusted_total")):.1f}</strong></div>' for r in rs[:20])
def news(xs):
    return ''.join(f'<div class="news"><b>{esc(x.get("title"))}</b><small>{esc(x.get("pubDate"))}</small></div>' for x in xs[:8]) or '<span class="muted">暂无</span>'
def main():
    d=load('seven_factor_latest.json'); e=load('evening_latest.json'); m=load('morning_latest.json'); c=list(d.get('candidates') or [])
    if not c: raise RuntimeError('candidate pool empty; refuse to overwrite dashboard')
    c.sort(key=lambda r:(int(n((r.get('recency') or {}).get('tier'),99)),-n(r.get('adjusted_total')))); focus=[r for r in c if r.get('pool')=='重点观察'][:8]; ready=[r for r in c if r.get('pool')=='预备池']; watch=[r for r in c if r.get('pool')=='观察池']
    s=d.get('market_sentiment') or {}; sc=n(s.get('sentiment_score'),50); action='积极参与' if sc>=70 else '结构性参与' if sc>=55 else '轻仓试错' if sc>=40 else '谨慎观察'
    topsec=sorted(d.get('sector_rankings') or [],key=lambda x:n(x.get('avg_change')),reverse=True)[:6]
    over=set(x.get('code') for x in e.get('focus_candidates') or []); overlap=sum(1 for r in focus if r.get('code') in over)
    T=Template(r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>七因子·第三阶段</title><style>:root{--bg:#090d13;--p:#131a23;--p2:#18212c;--l:#283443;--t:#edf2f8;--m:#8794a7;--b:#6ea8ff;--u:#ff6575;--d:#35d29a;--g:#f3c75b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font:14px -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}.wrap{max-width:1450px;margin:auto;padding:20px}.top{display:flex;justify-content:space-between;margin-bottom:14px}.top h1{margin:0;font-size:25px}.muted,small{color:var(--m)}.hero,.split{display:grid;grid-template-columns:1.2fr 1fr;gap:12px}.box{background:var(--p);border:1px solid var(--l);border-radius:14px;padding:16px}.action{font-size:28px;font-weight:900}.score{font-size:38px;font-weight:900}.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:12px}.mini,.row,.news{background:#0e141c;border:1px solid #222d3a;border-radius:8px;padding:8px}.mini b{display:block;font-size:16px}.up{color:var(--u)}.down{color:var(--d)}.section{margin-top:12px}.section h2{font-size:16px;margin:0 0 4px}.focusgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.stock{display:grid;grid-template-columns:50px 1.5fr 85px 70px auto;gap:8px;align-items:center;background:var(--p2);border:1px solid var(--l);border-radius:11px;padding:11px}.rank{color:var(--g);font-size:10px}.name b{display:block}.name small{font-size:9px}.stock>div>strong{display:block}.score b{font-size:20px}.pill{display:inline-block;padding:4px 7px;background:#252c35;border-radius:6px;font-size:9px;white-space:nowrap}.metrics{grid-column:1/-1;display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.metrics span{background:#0d131a;padding:6px;border-radius:6px;font-size:8px;color:var(--m)}.metrics b{color:var(--t)}.gold{color:var(--g)}details{grid-column:1/-1}.tag{display:inline-block;font-size:8px;padding:3px 5px;background:#1d2631;border:1px solid #2a3746;border-radius:5px;margin:2px}.rows{display:flex;flex-direction:column;gap:5px}.row{display:grid;grid-template-columns:1fr 100px 45px 55px;gap:6px;font-size:10px}.news{margin-bottom:5px}.news b{display:block;font-size:9px}.news small{font-size:8px}.sector{display:flex;flex-wrap:wrap;gap:6px}.sector span{background:#0e141c;border:1px solid #222d3a;border-radius:7px;padding:7px;font-size:9px}.footer{text-align:center;color:#657285;font-size:9px;padding:18px}@media(max-width:900px){.hero,.split,.focusgrid{grid-template-columns:1fr}}@media(max-width:650px){.wrap{padding:11px}.grid4{grid-template-columns:1fr 1fr}.stock{grid-template-columns:35px 1fr 75px}.stock .pill,.score{grid-column:2}.metrics{grid-template-columns:1fr 1fr}.row{grid-template-columns:1fr 75px 40px 50px}}</style><div class="wrap"><div class="top"><div><h1>七因子 · 决策仪表盘</h1><div class="muted">收盘选股 → 20:00晚间预判 → 08:00隔夜修正 → 等待9:25竞价</div></div><div class="muted">A股：$DATE $TIME<br>20:00：$EVENING<br>08:00：$MORNING</div></div><div class="hero"><div class="box"><div class="muted">当前市场状态</div><div class="action">$ACTION</div><div class="muted">情绪分 $SCORE · $LABEL</div><div class="grid4"><div class="mini">涨停<b>$LUP</b></div><div class="mini">跌停<b>$LDN</b></div><div class="mini">最高连板<b>$MAX</b></div><div class="mini">炸板率<b>$EXP%</b></div></div></div><div class="box"><div class="grid4"><div class="mini">重点观察<b>$FOCUS</b></div><div class="mini">20:00仍在重点池<b>$OVERLAP</b></div><div class="mini">预备池<b>$READY</b></div><div class="mini">观察池<b>$WATCH</b></div></div></div></div><section class="box section"><h2>① 明日重点观察</h2><div class="muted">七因子负责选股；这里看排序与证据</div><div class="focusgrid" style="margin-top:9px">$FOCUS_HTML</div></section><section class="box section"><h2>② 20:00 晚间预判</h2><div class="muted">消息层只修正预期，不修改七因子评分</div><div class="split" style="margin-top:9px"><div class="rows">$EVENING_ROWS</div><div>$EVENING_NEWS</div></div></section><section class="box section"><h2>③ 08:00 隔夜修正</h2><div class="muted">重大消息 → 调整优先级；证据不足 → 保持结论，等待竞价</div><div class="split" style="margin-top:9px"><div>$MORNING_NEWS</div><div class="box" style="padding:10px">重大利空：降级/移出观察<br><br>主线催化：优先级上调，但不改七因子<br><br>证据不足：保持原结论 → 9:25验证</div></div></section><section class="box section"><h2>④ 主线与板块</h2><div class="sector" style="margin-top:8px">$SECTORS</div></section><section class="box section"><h2>⑤ 预备池 / 观察池</h2><div class="rows" style="margin-top:8px">$ROWS</div></section><div class="footer">第三阶段 · 消息层与七因子解耦 · 仅供研究参考，不构成投资建议</div></div>''')
    page=T.substitute(DATE=esc(d.get('scan_date')),TIME=esc(d.get('scan_time')),EVENING=esc(e.get('generated_at','尚未生成')),MORNING=esc(m.get('generated_at','尚未生成')),ACTION=action,SCORE=f'{sc:.1f}',LABEL=esc(s.get('sentiment_label','正常')),LUP=esc(s.get('limit_up_count')),LDN=esc(s.get('limit_down_count')),MAX=esc(s.get('max_boards_est')),EXP=esc(s.get('explosion_rate')),FOCUS=len(focus),OVERLAP=overlap,READY=len(ready),WATCH=len(watch),FOCUS_HTML=''.join(card(r,i+1) for i,r in enumerate(focus)) or '<div class="muted">暂无重点观察</div>',EVENING_ROWS=''.join(f'<div class="row"><b>{esc(x.get("name"))}</b><span>{esc(x.get("sector"))}</span><span>P{esc(x.get("tier"))}</span><strong>{n(x.get("score")):.1f}</strong></div>' for x in (e.get('focus_candidates') or [])[:10]) or '<span class="muted">暂无</span>',EVENING_NEWS=news(e.get('headlines') or []),MORNING_NEWS=news(m.get('overnight_headlines') or []),SECTORS=''.join(f'<span>#{esc(s.get("rank"))} {esc(s.get("name"))} <b class="{pc(s.get("avg_change"))}">{pct(s.get("avg_change"))}</b></span>' for s in topsec),ROWS=rows(ready+watch))
    os.makedirs(os.path.dirname(OUT),exist_ok=True)
    with open(OUT,'w',encoding='utf-8') as f:f.write(page)
    print('generated',len(page),'bytes')
if __name__=='__main__':main()
